'use strict';
const G11Sync=(()=>{
  let ref=null,feedbackRef=null,connectionRef=null,imagesRef=null,images={},remoteSeq=0,queue={},known={},remote=null,feedback={},timer=null,running=false,online=true,status='local',error='',listeners=[],pendingKey='',backup=null;
  const emit=()=>{for(const fn of listeners)fn({status,error,online,feedback,backup});};
  const keyName=(kind,key)=>kind+'/'+key;
  const cleanShots=value=>Array.isArray(value)?value.slice(0,2).filter(item=>item&&typeof item.name==='string'&&typeof item.data==='string'&&item.data.startsWith('data:image/jpeg;base64,')&&item.data.length<=320000).map(item=>({name:item.name.slice(0,120),data:item.data})):[];
  function cleanPractice(value){const result={projects:{},lessons:{},target:{}};for(const s of BSD_SOURCES){const r=value?.projects?.[s.name];if(r&&(r.evidence||r.ready||known[keyName("projects",s.name)]||remote?.projects?.[s.name]))result.projects[s.name]={evidence:String(r.evidence||'').slice(0,4000),ready:r.ready===true};}for(const l of LESSONS){const r=value?.lessons?.[l.id];if(r&&(r.evidence||r.reflection||r.done||r.screenshots?.length||r.quiz?.best!==null&&r.quiz?.best!==undefined||known[keyName("lessons",l.id)]||remote?.lessons?.[l.id])){const screenshots=cleanShots(r.screenshots);result.lessons[l.id]={evidence:String(r.evidence||'').slice(0,4000),reflection:String(r.reflection||'').slice(0,4000),screenshots:screenshots.length?screenshots:null,done:r.done===true,quiz:{draft:Array.isArray(r.quiz?.draft)?r.quiz.draft.slice(0,2).map(x=>[0,1,2].includes(x)?x:-1):[],best:Number.isFinite(r.quiz?.best)?r.quiz.best:-1,last:Number.isFinite(r.quiz?.last)?r.quiz.last:-1}};}}if(value?.target?.date)result.target={date:String(value.target.date).slice(0,10),unitId:UNITS.some(u=>u.id===value.target.unitId)?value.target.unitId:'live',goal:String(value.target.goal||'').slice(0,600)};return result;}
  function entries(value){return [...Object.entries(value.projects||{}).map(([k,v])=>[keyName('projects',k),v]),...Object.entries(value.lessons||{}).map(([k,v])=>[keyName('lessons',k),v]),...(value.target?.date?[['target',value.target]]:[])];}
  function canonical(value){if(Array.isArray(value))return value.map(canonical);if(value&&typeof value==='object')return Object.fromEntries(Object.keys(value).sort().map(k=>[k,canonical(value[k])]));return value;}
  const equal=(a,b)=>JSON.stringify(canonical(a))===JSON.stringify(canonical(b));
  function noteValue(value){if(!value)return value;const r={...value};delete r.revision;delete r.updatedAt;delete r.updatedBy;if(r.quiz)r.quiz={draft:[],best:-1,last:-1,...r.quiz};return r;}
  /* Screenshot bytes live in learningEvidenceImages/{student}/{imageId}; lessons keep
   * only {name,imageId} so the teacher dashboard does not download every image. */
  async function imageId(data){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(data));return Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,32);}
  async function hydrate(value){const lessons=value?.lessons||{},missing=new Set();for(const l of Object.values(lessons))for(const s of Object.values(l?.screenshots||{}))if(s?.imageId&&!s.data&&!(s.imageId in images))missing.add(s.imageId);await Promise.all([...missing].map(id=>imagesRef.child(id).once('value').then(snap=>{images[id]=snap.val()?.data||'';}).catch(()=>{images[id]='';})));const result={...value,lessons:{}};for(const [key,l]of Object.entries(lessons))result.lessons[key]=l?.screenshots?{...l,screenshots:Object.values(l.screenshots).map(s=>({name:s.name,data:s.data||images[s.imageId]||''}))}:l;return result;}
  async function storeShots(value,lesson){if(!value?.screenshots)return value;const shots=[];for(const shot of value.screenshots){const id=await imageId(shot.data);if(images[id]!==shot.data){const result=await imagesRef.child(id).transaction(current=>current?undefined:{data:shot.data,lesson:Number(lesson),createdAt:G11CloudIdentity.stamp(),createdBy:G11CloudIdentity.studentUid});if(!result.snapshot.exists())throw Error('Screenshot not saved');images[id]=shot.data;}shots.push({name:shot.name,imageId:id});}return {...value,screenshots:shots};}
  function persist(){try{localStorage.setItem(pendingKey,JSON.stringify(queue));}catch{error=t('Browser tidak dapat menyimpan antrean offline. Unduh bukti sebelum menutup.','This browser cannot keep the offline queue. Download evidence before closing.');emit();}}
  function overlay(base){const result={projects:{},lessons:{},target:{}};for(const [path,v]of entries(base)){const [kind,key]=path.split('/');if(kind==='target')result.target=noteValue(v);else result[kind][key]=noteValue(v);}for(const [path,v]of Object.entries(queue)){const [kind,key]=path.split('/');if(kind==='target')result.target=v;else result[kind][key]=v;}for(const v of Object.values(result.lessons)){v.quiz??={draft:[],best:-1,last:-1};v.quiz.best=v.quiz.best===-1?null:v.quiz.best;v.quiz.last=v.quiz.last===-1?null:v.quiz.last;v.quiz.draft=(v.quiz.draft||[]).map(x=>x===-1?null:x);}return result;}
  async function flush(){if(!ref||running||!Object.keys(queue).length)return;running=true;status=online?'saving':'offline';emit();try{for(const [path,value]of Object.entries(queue)){const text=JSON.stringify(value),stored=path.startsWith('lessons/')?await storeShots(value,path.split('/')[1]):value;await ref.child(path).transaction(current=>({...current,...stored,revision:(Number(current?.revision)||0)+1,updatedAt:G11CloudIdentity.stamp(),updatedBy:G11CloudIdentity.studentUid}));if(JSON.stringify(queue[path])===text)delete queue[path];persist();}status=Object.keys(queue).length?'pending':'synced';error='';}catch(e){status='error';error=e.code==='PERMISSION_DENIED'?t('Sesi atau izin Firebase berubah. Masuk kembali; catatan belum terkirim tetap disimpan.','Firebase access changed. Sign in again; unsent notes remain saved.'):t('Belum terkirim ke Firebase. Catatan tetap ada di browser; coba kirim ulang.','Not yet sent to Firebase. Notes remain on this browser; retry syncing.');}finally{running=false;emit();if(status!=='error'&&Object.keys(queue).length)timer=setTimeout(flush,700);}}
  function enqueue(value){if(!ref)return;const data=cleanPractice(value);for(const [path,r]of entries(data)){const text=JSON.stringify(r);if(known[path]!==text){known[path]=text;queue[path]=r;}}if(Object.keys(queue).length){persist();status=online?'pending':'offline';emit();clearTimeout(timer);timer=setTimeout(flush,650);}}
  async function init(local,onRemote){if(g11Session.isLocalPreview||g11Session.isTeacherPreview||typeof db==='undefined'){status='local';return local;}const identity=await G11CloudIdentity.restore(g11Session.id);G11CloudIdentity.studentUid=identity.user.uid;ref=identity.db.ref('learningProgress').child(g11Session.id).child('grade11Ai').child('student');feedbackRef=identity.db.ref('learningProgress').child(g11Session.id).child('grade11Ai').child('teacher');connectionRef=identity.db.ref('.info/connected');imagesRef=identity.db.ref('learningEvidenceImages').child(g11Session.id);pendingKey='cs-report-grade11-pending:'+g11Session.id;try{queue=JSON.parse(localStorage.getItem(pendingKey)||'{}')||{};}catch{queue={};}let loadTimer,initialLoaded=true;try{remote=await hydrate((await Promise.race([ref.once('value'),new Promise((_,reject)=>{loadTimer=setTimeout(()=>reject(Error('offline')),8000);})])).val()||{});}catch(e){if(e.code==='PERMISSION_DENIED')throw e;online=false;initialLoaded=false;remote=cleanPractice(local);}finally{clearTimeout(loadTimer);}const cleaned=cleanPractice(local);for(const [path,v]of entries(cleaned)){const [kind,key]=path.split('/'),server=kind==='target'?remote.target:remote[kind]?.[key];if(!server)queue[path]??=v;else if(!equal(noteValue(server),v)&&!queue[path])backup??=local;}if(backup)try{localStorage.setItem('cs-report-grade11-migration-backup:'+g11Session.id,JSON.stringify(backup));}catch{}else try{backup=JSON.parse(localStorage.getItem('cs-report-grade11-migration-backup:'+g11Session.id)||'null');}catch{}persist();const merged=overlay(remote);for(const [path,v]of entries(cleanPractice(merged)))known[path]=JSON.stringify(v);ref.on('value',async snap=>{const seq=++remoteSeq,value=await hydrate(snap.val()||{});if(seq!==remoteSeq)return;remote=value;if(!initialLoaded){initialLoaded=true;for(const [path,v]of entries(cleaned)){const [kind,key]=path.split('/'),server=kind==='target'?remote.target:remote[kind]?.[key];if(!server)queue[path]??=v;else if(!equal(noteValue(server),v)&&!queue[path]){backup??=local;try{localStorage.setItem('cs-report-grade11-migration-backup:'+g11Session.id,JSON.stringify(backup));}catch{}}}persist();flush();}const next=overlay(remote);for(const [path,v]of entries(cleanPractice(next)))known[path]=JSON.stringify(v);onRemote(next);},()=>{status='error';error=t('Sesi cloud berubah. Masuk kembali dari CS.Report. Catatan yang belum terkirim tetap disimpan.','Cloud access changed. Sign in again from CS.Report. Unsent notes remain saved.');emit();});feedbackRef.on('value',snap=>{feedback=snap.val()?.reviews||{};emit();},()=>{status='error';error=t('Feedback belum termuat. Coba kirim ulang.','Feedback could not load. Retry syncing.');emit();});connectionRef.on('value',snap=>{online=snap.val()===true;if(!online)status='offline';else if(Object.keys(queue).length){status='pending';flush();}else status='synced';emit();});flush();return merged;}
  function review(kind,id){const path=kind==='projects'?'p_'+id:'l_'+id,r=feedback[path],source=remote?.[kind]?.[id];if(!r)return null;return {...r,current:r.sourceRevision===(source?.revision||0)};}
  function statusText(){return status==='synced'?t('✓ Tersimpan untuk guru','✓ Saved for your teacher'):status==='local'?t('Mode review lokal · tidak mengirim data','Local review mode · no data sent'):status==='offline'?t('Offline · perubahan menunggu koneksi','Offline · changes are waiting for a connection'):status==='saving'?t('Menyimpan…','Saving…'):status==='error'?error:t('Menunggu sinkronisasi…','Waiting to sync…');}
  return {dispose(){clearTimeout(timer);ref?.off();feedbackRef?.off();connectionRef?.off();ref=null;listeners=[];},init,enqueue,flush,review,statusText,subscribe(fn){listeners.push(fn);fn({status,error,online,feedback,backup});},backup:()=>backup};
})();
